using System.Text.Json;

namespace MyApp.Evals.Tests;

internal static class Thresholds
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "quality.thresholds.json");
        if (!File.Exists(path)) return;

        var doc = JsonDocument.Parse(File.ReadAllText(path));
        var hardFail = doc.RootElement.TryGetProperty("hard_fail", out var hf) && hf.GetBoolean();

        if (!doc.RootElement.TryGetProperty("thresholds", out var thresholds))
            return;

        foreach (var metric in result.Metrics)
        {
            if (!thresholds.TryGetProperty(metric.Key, out var threshold))
                continue;

            if (metric.Value is NumericMetric nm && nm.Value.HasValue)
            {
                if (threshold.TryGetProperty("min_value", out var minVal) && nm.Value < (decimal)minVal.GetDouble())
                {
                    var msg = $"[Threshold] {scenarioId}/{metric.Key}: {nm.Value} < min {minVal.GetDouble()}";
                    if (hardFail) Assert.Fail(msg);
                    else Console.WriteLine(msg);
                }
                if (threshold.TryGetProperty("max_value", out var maxVal) && nm.Value > (decimal)maxVal.GetDouble())
                {
                    var msg = $"[Threshold] {scenarioId}/{metric.Key}: {nm.Value} > max {maxVal.GetDouble()}";
                    if (hardFail) Assert.Fail(msg);
                    else Console.WriteLine(msg);
                }
            }
        }
    }
}

