        }

        // Parse connection string and build IChatClient via Microsoft.Extensions.AI
        var parts = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var segment in connectionString.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var idx = segment.IndexOf('=');
            if (idx > 0)
                parts[segment[..idx].Trim()] = segment[(idx + 1)..].Trim();
        }

        parts.TryGetValue("Endpoint", out var endpoint);
        parts.TryGetValue("Key", out var key);
        parts.TryGetValue("DeploymentId", out var deploymentId);

        if (string.IsNullOrEmpty(endpoint))
            throw new InvalidOperationException(
                $"ConnectionStrings:chat is set but missing 'Endpoint'. Value: {connectionString}");

        IChatClient client;
        if (!string.IsNullOrEmpty(key))
        {
            client = new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new System.ClientModel.ApiKeyCredential(key))
                .GetChatClient(deploymentId ?? "chat")
                .AsIChatClient();
        }
        else
        {
            client = new Azure.AI.OpenAI.AzureOpenAIClient(
                new Uri(endpoint),
                new Azure.Identity.DefaultAzureCredential())
                .GetChatClient(deploymentId ?? "chat")
                .AsIChatClient();
        }

        return client;
    }
}

